import {
	AnythingLauncherModule,
	AnythingLauncherReloadOverlayModule
} from '@anythingai/launcher'
import retry from 'async-retry'
import { Directory, File, Paths } from 'expo-file-system'
import { fetch } from 'expo/fetch'
import { getMetroBundleURLFromHost } from './getMetroBundleURLFromHost'
import { useAuthStore } from '@/stores'

export const launchPreviewApp = async ({ bundleURL }: { bundleURL: URL }) => {
	const bundleId = bundleURL.pathname.split('/').pop()
	const bundlesDir = new Directory(Paths.cache, 'bundles')
	bundlesDir.create({ idempotent: true })
	const fileBundle = new File(bundlesDir, bundleId + '.bundle')
	AnythingLauncherReloadOverlayModule?.show(
		!fileBundle.exists,
		!fileBundle.exists
	)
	if (!fileBundle.exists) {
		const accessToken = useAuthStore.getState().auth?.accessToken
		if (!accessToken) {
			throw new Error('No access token')
		}
		const response = await retry(
			async () => {
				const response = await fetch(bundleURL.toString(), {
					headers: { Authorization: accessToken }
				})
				if (!response.ok) {
					throw new Error(`Bundle URL not reachable: ${response.status}`)
				}
				return response
			},
			{
				factor: 2,
				retries: 10,
				minTimeout: 500,
				maxTimeout: 5000
			}
		)

		const contentLength = response.headers.get('content-length')
		const total = contentLength ? parseInt(contentLength, 10) : NaN
		const reader = response.body?.getReader()
		if (reader) {
			let received = 0
			const chunks: Uint8Array[] = []

			while (true) {
				const { done, value } = await reader.read()
				if (done) break

				chunks.push(value)
				received += value.length

				if (!isNaN(total)) {
					AnythingLauncherReloadOverlayModule?.update(
						`Downloading`,
						received / total
					)
				}
			}

			const totalLength = chunks.reduce((sum, chunk) => sum + chunk.length, 0)
			const combined = new Uint8Array(totalLength)
			let offset = 0
			for (const chunk of chunks) {
				combined.set(chunk, offset)
				offset += chunk.length
			}

			fileBundle.write(combined)
		} else {
			fileBundle.write(await response.bytes())
		}
	}
	return AnythingLauncherModule?.open(fileBundle.uri, false, false, false)
}

export const launchMetroServerApp = async ({
	metroServerHost,
	isWeb
}: {
	metroServerHost: string
	isWeb: boolean
}) => {
	try {
		const bundleURL = getMetroBundleURLFromHost({ host: metroServerHost })
		AnythingLauncherModule?.open(bundleURL.toString(), true, true, isWeb)
	} catch (error) {
		AnythingLauncherReloadOverlayModule?.hide()
		console.error(`Bundle URL not reachable: ${error}`)
	}
}
